import React, { useState, useEffect } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";

// --- API Helpers ---
async function fetchFacilities(borough = "") {
  const url = borough ? `/api/facilities?borough=${borough}` : "/api/facilities";
  const res = await fetch(url);
  return res.json();
}

async function sendChat(role, message, facility_id = null) {
  const res = await fetch("/api/chat", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ role, message, facility_id }),
  });
  return res.json();
}

function App() {
  const [facilities, setFacilities] = useState([]);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");

  // Load facilities once
  useEffect(() => {
    fetchFacilities().then((data) => {
      console.log("Facilities:", data); // debug
      setFacilities(data);
    });
  }, []);

  // Handle chat submit
  const handleSend = async () => {
    if (!input.trim()) return;
    const newMsg = { role: "user", message: input };
    setMessages((prev) => [...prev, newMsg]);
    setInput("");

    const reply = await sendChat("user", input);
    setMessages((prev) => [...prev, { role: "assistant", message: reply.reply }]);
  };

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      {/* Map Section */}
      <div style={{ flex: 2 }}>
        <MapContainer center={[40.7128, -74.006]} zoom={12} style={{ height: "100%", width: "100%" }}>
          <TileLayer
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            attribution="&copy; OpenStreetMap contributors"
          />
          {facilities.map((f) => (
            <Marker key={f.id} position={[f.latitude, f.longitude]}>
              <Popup>
                <b>{f.name}</b>
                <br />
                <button
                  onClick={async () => {
                    const reply = await sendChat("user", "Tell me about this place", f.id);
                    setMessages((prev) => [...prev, { role: "assistant", message: reply.reply }]);
                  }}
                >
                  Ask about this place
                </button>
              </Popup>
            </Marker>
          ))}
        </MapContainer>
      </div>

      {/* Chat Section */}
      <div style={{ flex: 1, borderLeft: "1px solid #ddd", display: "flex", flexDirection: "column" }}>
        <div style={{ flex: 1, overflowY: "auto", padding: "10px" }}>
          {messages.map((m, i) => (
            <div key={i} style={{ margin: "5px 0", color: m.role === "user" ? "blue" : "green" }}>
              <b>{m.role}:</b> {m.message}
            </div>
          ))}
        </div>
        <div style={{ padding: "10px", borderTop: "1px solid #ddd" }}>
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask something..."
            style={{ width: "80%" }}
          />
          <button onClick={handleSend} style={{ width: "18%", marginLeft: "2%" }}>
            Send
          </button>
        </div>
      </div>
    </div>
  );
}

export default App;
